:root {
  color: #19232d;
  background: #f4f6f8;
  font: 16px/1.5 system-ui, sans-serif;
}

body { margin: 0; }
.shell { max-width: 760px; margin: 4rem auto; padding: 0 1.5rem; }
h1 { margin: 0 0 1.5rem; font-size: 2rem; }
.create-form { display: grid; grid-template-columns: 1fr auto; gap: .5rem .75rem; align-items: center; }
.create-form label { grid-column: 1 / -1; font-weight: 600; }
input, button { min-height: 2.75rem; border-radius: .4rem; font: inherit; }
input { border: 1px solid #8a96a3; padding: 0 .75rem; background: white; }
button { border: 0; padding: 0 1rem; background: #1769aa; color: white; font-weight: 600; cursor: pointer; }
button:hover { background: #105589; }
button:focus-visible, input:focus-visible { outline: 3px solid #f0a000; outline-offset: 2px; }
.alert { color: #a52222; font-weight: 600; }
.projects { display: grid; gap: .75rem; margin-top: 2rem; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem; background: white; border: 1px solid #d7dde3; border-radius: .5rem; }
